function maxProduct(nums: number[]): number {
  let max = nums[0]
  let min = nums[0]
  let best = nums[0]
  for (let i = 1; i < nums.length; i++) {
    const n = nums[i]
    const candidates = [n, max * n, min * n]
    max = Math.max(...candidates)
    min = Math.min(...candidates)
    best = Math.max(best, max)
  }
  return best
}
